};

function fmtDate(value) {
  if (!value) return null;
  try { return new Intl.DateTimeFormat('ru-RU', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Qyzylorda' }).format(new Date(value)); }
  catch (error) { return String(value); }
}
function clean(value) { return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
function stripPipes(value) { return clean(value).replace(/\|+/g, ' ').replace(/\s+/g, ' ').trim(); }
function renderValue(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return stripPipes(value);
  if (Array.isArray(value)) return value.map(renderValue).filter(Boolean).join('; ');
  if (typeof value === 'object') {
    const preferred = ['name','title','criterion','axis','item','place','summary','text','value','finding','comparison','recommendation','why_relevant'];
    const parts = [];
    for (const key of preferred) if (value[key] !== undefined && value[key] !== null && clean(renderValue(value[key]))) parts.push(renderValue(value[key]));
