function looksLikeBadResult(row) {
  const title = clean(row.title).toLowerCase();
  const url = clean(row.url).toLowerCase();
  return title.includes('[pdf]') || title.includes('pdf') || url.endsWith('.pdf');
}
function pickRating(text) { return (text.match(/(?:rating|score|stars)[^0-9]{0,20}(\d(?:[.,]\d)?)/i) || text.match(/\b([1-5][.,]\d)\b/))?.[1] || ''; }
