  ];
  if (caveats.length) sections.push(`<b>${L.limits}</b>\n${caveats.join('\n')}`);
  sections.push(`<b>${L.comparison}</b>\n${comparison.join('\n') || whatFound.join('\n') || L.notSpecified}`);
  sections.push(`<b>${L.conclusion}</b>\n${stripPipes(report.conclusion) || L.notSpecified}`);
  sections.push(`<b>${L.recommendation}</b>\n${recommendations.join('\n') || L.notSpecified}`);
  sections.push(`<b>${L.sources}</b>\n${sources.join('\n') || L.notSpecified}`);
  return sections.join('\n\n');
}
